//! WU-014: independently seeded, deterministic 3n-clause dense random 2-XNF.
//! Approximate reconstruction of the *distributional description* in
//! j-danner/2xnf_sat_solving/benchmark/rand/README.md, not its exact generator.
//! Planted formulas are generated by flipping a linear form's constant when
//! both forms initially fail under the planted witness.
//!
//! Usage: wu014_generate_xnf OUT_DIR N_MIN N_MAX CASES_PER_N BASE_SEED
//! This generator only generates input cases; it does NOT solve SAT.

use std::fs;
use std::path::PathBuf;

#[derive(Clone)]
struct Rng(u64);

impl Rng {
    fn new(seed: u64) -> Self {
        Self(if seed == 0 { 0xa0761d6478bd642f } else { seed })
    }
    fn draw(&mut self) -> u64 {
        self.0 ^= self.0 >> 12;
        self.0 ^= self.0 << 25;
        self.0 ^= self.0 >> 27;
        self.0.wrapping_mul(0x2545f4914f6cdd1d)
    }
    fn bit(&mut self) -> bool { self.draw() & 1 != 0 }
    fn support(&mut self, n: usize) -> u64 {
        let all = (1u64 << n) - 1;
        loop {
            let s = self.draw() & all;
            if s != 0 { return s; }
        }
    }
}

fn truth(mask: u64, negated: bool, assignment: u64) -> bool {
    ((mask & assignment).count_ones() & 1 != 0) != negated
}

fn lineral(mask: u64, negated: bool, n: usize) -> String {
    let body = (1..=n).filter(|var| mask & (1u64 << (var - 1)) != 0)
        .map(|var| var.to_string()).collect::<Vec<_>>().join("+");
    format!("{}{body}", if negated { "-" } else { "" })
}

fn generate(n: usize, seed: u64, planted: bool) -> (String, Option<u64>) {
    assert!((1..=40).contains(&n));
    let mut rng = Rng::new(seed);
    let witness = planted.then(|| rng.support(n));
    let mut output = format!("c witnora WU-014 independent synthetic seed {seed}\n\
        c family {} (not identical to 2024 original benchmark generator)\n\
        p xnf {n} {}\n", if planted { "planted" } else { "unplanted" }, 3*n);
    for _ in 0..3*n {
        let a = rng.support(n);
        let b = rng.support(n);
        let na = rng.bit();
        let mut nb = rng.bit();
        if let Some(model) = witness {
            if !truth(a, na, model) && !truth(b, nb, model) {
                nb = !nb;
            }
        }
        output.push_str(&format!("{} {} 0\n", lineral(a, na, n), lineral(b, nb, n)));
    }
    (output, witness)
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args: Vec<String> = std::env::args().collect();
    if args.len() != 6 { return Err("usage: wu014_generate_xnf OUT_DIR N_MIN N_MAX CASES_PER_N BASE_SEED".into()); }
    let outdir = PathBuf::from(&args[1]);
    let low = args[2].parse::<usize>()?;
    let high = args[3].parse::<usize>()?;
    let count = args[4].parse::<usize>()?;
    let base = args[5].parse::<u64>()?;
    if !(21..=40).contains(&low) || !(low..=40).contains(&high) || count == 0 || count > 100 {
        return Err("n must be in 21..40, nondecreasing, 1 <= cases_per_n <= 100".into());
    }
    fs::create_dir_all(&outdir)?;
    let mut manifest = String::from("family\tvariables\tseed\tfile\tplanted_witness_bits\n");
    for n in low..=high {
        for i in 0..count {
            for planted in [false, true] {
                let family = if planted { "planted" } else { "unplanted" };
                // Stable distinct seeds per family, n and repetition index.
                let seed = base.wrapping_add((n as u64) << 32)
                    .wrapping_add((i as u64) << 1).wrapping_add(u64::from(planted));
                let (formula, witness) = generate(n, seed, planted);
                let filename = format!("{family}_n{n}_seed{seed}.xnf");
                fs::write(outdir.join(&filename), formula)?;
                let witness_str = witness.map_or_else(String::new, |m| format!("0x{m:x}"));
                manifest.push_str(&format!("{family}\t{n}\t{seed}\t{filename}\t{witness_str}\n"));
            }
        }
    }
    fs::write(outdir.join("manifest.tsv"), manifest)?;
    println!("WU-014 generated {} original-seed-independent XNF cases in {}",
        2 * (high - low + 1) * count, outdir.display());
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn seeded_replay_is_byte_exact_and_planted_witness_valid() {
        let (first, witness) = generate(25, 123456, true);
        assert_eq!(generate(25, 123456, true).0, first);
        let model = witness.unwrap();
        let body = first.lines().filter(|l| !l.starts_with('c') && !l.starts_with('p'));
        assert_eq!(body.clone().count(), 75);
        for clause in body {
            let terms: Vec<_> = clause.split_whitespace().collect();
            assert_eq!(terms.len(), 3);
            let eval = |term: &str| -> bool {
                let neg = term.starts_with('-');
                let clean = term.trim_start_matches('-');
                let support = clean.split('+').map(|x| 1u64 << (x.parse::<usize>().unwrap()-1))
                    .fold(0, |acc, val| acc | val);
                truth(support, neg, model)
            };
            assert!(eval(terms[0]) || eval(terms[1]));
        }
    }

    #[test]
    fn independent_families_and_density() {
        let (a, none) = generate(28, 8899, false);
        let (b, some) = generate(28, 8899, true);
        assert_ne!(a, b);
        assert!(none.is_none() && some.is_some());
        assert_eq!(a.lines().filter(|l| l.ends_with(" 0")).count(), 84);
    }
}
